import { useEffect, useRef } from 'react';

import {
  usePageCacheBaseState,
  usePageCacheLoadingGate,
  useResolvedPageHash,
} from 'hooks/usePageCache/shared';
import { PageCacheService } from 'services/PageCacheService/PageCacheService';
import { compressToBase64, decompressFromBase64 } from 'utils/compression';
import { waitForCanvasStability } from 'utils/pageCache';

// Yield control back to the browser event loop so it can paint frames and
// handle input before the next heavy synchronous step.
const yieldToMain = (): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, 0));

export interface UsePageCacheProps {
  pageName: string;
  containerRef: React.RefObject<HTMLDivElement>;
  enabled?: boolean;
  isPageReady?: boolean;
}

export interface UsePageCacheResult {
  cachedHtml: string | null;
  isCacheChecking: boolean;
  isCacheHit: boolean;
  isStaleHit: boolean;
  shouldRevalidate: boolean;
}

export const usePageCache = ({
  pageName,
  containerRef,
  enabled = true,
  isPageReady = false,
}: UsePageCacheProps): UsePageCacheResult => {
  const {
    cachedHtml,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    setCachedHtml,
    setIsCacheChecking,
    setIsCacheHit,
    setIsStaleHit,
    setShouldRevalidate,
    checkedHashRef,
    abortControllerRef,
  } = usePageCacheBaseState();

  const { pageHash } = useResolvedPageHash(pageName);

  useEffect(() => {
    if (!enabled || !pageHash || pageHash === checkedHashRef.current) return;

    checkedHashRef.current = pageHash;

    abortControllerRef.current?.abort();
    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    setIsCacheChecking(true);
    setCachedHtml(null);
    setIsCacheHit(false);
    setIsStaleHit(false);
    setShouldRevalidate(false);

    PageCacheService.getInstance()
      .get(pageName, pageHash, abortController.signal)
      .then(async (result) => {
        if (abortController.signal.aborted) return;

        if (result?.html) {
          const html = decompressFromBase64(result.html);
          setCachedHtml(html);
          setIsCacheHit(true);
          setIsStaleHit(!!result.isStale);
          setShouldRevalidate(!!result.shouldRevalidate);
        }

        setIsCacheChecking(false);
      })
      .catch(() => {
        if (!abortController.signal.aborted) {
          setIsCacheChecking(false);
        }
      });

    return () => {
      abortController.abort();
    };
  }, [enabled, pageName, pageHash]);

  const submittedHashRef = useRef<string>('');
  const wasLoadingRef = usePageCacheLoadingGate(
    isPageReady,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
  );

  useEffect(() => {
    if (!enabled || !isPageReady || !pageHash || isCacheChecking) return;

    const shouldSubmitByState = !isCacheHit || (isStaleHit && shouldRevalidate);
    if (!shouldSubmitByState) return;
    if (!wasLoadingRef.current) return;
    if (submittedHashRef.current === pageHash) return;
    if (!containerRef.current) return;

    submittedHashRef.current = pageHash;

    const scheduleCapture = (fn: () => void): (() => void) => {
      if (typeof requestIdleCallback !== 'undefined') {
        const id = requestIdleCallback(fn, { timeout: 5000 });
        return () => cancelIdleCallback(id);
      }
      const id = setTimeout(fn, 200);
      return () => clearTimeout(id);
    };

    let cancelled = false;

    const captureAndSubmit = async () => {
      if (!containerRef.current) return;

      try {
        await waitForCanvasStability(containerRef.current);
        if (cancelled || !containerRef.current) return;

        const element = containerRef.current;
        const totalWidth = element.scrollWidth;

        const { snapdom } = await import('@zumer/snapdom');

        let result;
        try {
          result = await snapdom(element, {
            dpr: 1,
            scale: 0.5,
            backgroundColor: '#ffffff',
            embedFonts: false,
            iconFonts: [],
            cache: 'full',
            fast: true,
            filter: (el: Element) => el.tagName !== 'IMG',
            filterMode: 'remove',
          });
        } catch (error) {
          console.error('Failed to capture page:', error);
        }

        if (cancelled || !result) return;

        const htmlContent = `<div style="width:${totalWidth}px;"><img src="${result.url}" style="width:100%;height:auto;display:block;" alt="cached-page" /></div>`;

        await yieldToMain();

        const compressed = compressToBase64(htmlContent);

        await PageCacheService.getInstance().set(
          pageName,
          pageHash,
          compressed,
        );
      } catch (error) {
        console.error('Failed to submit page to cache:', error);
      }
    };

    const cancelScheduled = scheduleCapture(() => {
      if (!cancelled) captureAndSubmit();
    });

    return () => {
      cancelled = true;
      cancelScheduled();
    };
  }, [
    enabled,
    isPageReady,
    pageName,
    pageHash,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    isCacheChecking,
    containerRef,
    wasLoadingRef,
  ]);

  return {
    cachedHtml,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
  };
};
